/** Destructive only within an explicitly disposable tax_test_* schema. No mocked database. */
final class ConcurrentMysqlTests {
    private static int passed,concurrentRounds;private ConcurrentMysqlTests(){ }
    @FunctionalInterface private interface Test{void run()throws Exception;}
    private static void check(String name,Test test)throws Exception{String selected=System.getenv("TAX_CONCURRENT_SELECTED_GROUP");if(selected!=null&&!selected.equals(name))return;test.run();passed++;System.out.println("PASS "+name);}
    private static void eq(Object a,Object b){if(!java.util.Objects.equals(a,b))throw new AssertionError("MySQL assertion failed");}
    private static Map<String,Object> body(Object... pairs){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],pairs[i+1]);return out;}
    private static void problem(String code,Runnable work){try{work.run();}catch(Workspace.Problem p){eq(p.code,code);return;}throw new AssertionError("missing failure "+code);}
    private static Map<String,Object> command(Map<String,Object> row,String op,Object... pairs){Map<String,Object> p=body("operation",op,"request_id",Workspace.id(),"expected_revision",row.get("revision"));p.putAll(body(pairs));return p;}
    private static String create(Workspace w,String actor){return (String)w.createCase(actor,body("title","SQL sample case","request_id",Workspace.id())).get("id");}
    private static String status(Runnable action){try{action.run();return "APPLIED";}catch(Workspace.Problem p){return p.code;}}
    private static final class Time extends Clock {Instant now=Instant.now();@Override public ZoneId getZone(){return ZoneOffset.UTC;}@Override public Clock withZone(ZoneId ignored){return this;}@Override public Instant instant(){return now;}}
    public static void main(String[] args)throws Exception{
        if(args.length!=4)throw new IllegalArgumentException("disposable app-config admin-config key report required");Path appFile=Path.of(args[0]),adminFile=Path.of(args[1]),key=Path.of(args[2]),report=Path.of(args[3]);SqlConfig config=SqlConfig.load(appFile),admin=SqlConfig.load(adminFile);String serverVersion,driverVersion;
        try(Connection c=admin.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT DATABASE(),VERSION()")){r.next();if(!r.getString(1).matches("tax_test_[a-z0-9_]+"))throw new IllegalArgumentException("disposable schema required");serverVersion=r.getString(2);driverVersion=c.getMetaData().getDriverVersion();}
        Time time=new Time();String owner,other,operator,preparer;String password="SQL-test-"+Workspace.id();
        try(ConcurrentMysqlStore one=new ConcurrentMysqlStore(config,key);ConcurrentMysqlStore two=new ConcurrentMysqlStore(config,key)){
            Workspace a=new Workspace(one,time),b=new Workspace(two,time);owner=(String)a.register(body("username","sql_owner","display_name","SQL sample owner","password",password)).get("id");other=(String)a.register(body("username","sql_other","display_name","SQL other","password",password)).get("id");operator=(String)a.createOperator("sql_admin","SQL operator",password,"ADMIN").get("id");preparer=(String)a.createOperator("sql_staff","SQL preparer",password,"PREPARER").get("id");
            check("actual MySQL 8.4 and certificate-verified encrypted transport",()->{eq(serverVersion.startsWith("8.4."),true);try(Connection c=config.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SHOW SESSION STATUS LIKE 'Ssl_cipher'")){eq(r.next(),true);eq(r.getString(2).isBlank(),false);}});
            check("runtime user cannot execute schema changes",()->{try(Connection c=config.connect();Statement s=c.createStatement()){s.execute("CREATE TABLE runtime_must_not_create(id INT)");throw new AssertionError("runtime DDL allowed");}catch(SQLException expected){eq(expected.getErrorCode(),1142);}});
            check("a distinct store reads committed accounts and owner-bound cases",()->{String id=create(a,owner);eq(b.readCase(owner,id).get("id"),id);for(String actor:List.of(other,operator,preparer))problem("CASE_NOT_FOUND",()->b.readCase(actor,id));});
            check("wrong key is rejected before data can be overwritten",()->{Path wrong=Files.createTempDirectory("wrong-mysql-key-").resolve("key");try(RecordCrypto k=new RecordCrypto(wrong,true)){k.usernameTag("probe");}try(ConcurrentMysqlStore ignored=new ConcurrentMysqlStore(config,wrong)){ignored.backend();throw new AssertionError("wrong key accepted");}catch(javax.crypto.AEADBadTagException expected){/* authenticated failure */}});
            check("missing key cannot initialize over existing SQL records",()->{Path missing=Files.createTempDirectory("missing-mysql-key-").resolve("key");try{ConcurrentMysqlStore.initialize(admin,missing);throw new AssertionError("missing key recreated");}catch(java.io.IOException expected){eq(expected.getMessage(),"SQL data key unavailable");}eq(Files.exists(missing),false);});
            check("host identity mismatch is rejected with an otherwise trusted CA",()->{Map<String,Object> raw=Json.object(Files.readAllBytes(appFile));raw.put("host","127.0.0.1");Path mismatch=Files.createTempFile("mysql-host-mismatch-",".json");Files.setPosixFilePermissions(mismatch,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));Files.write(mismatch,Json.bytes(raw));try(Connection ignored=SqlConfig.load(mismatch).connect()){ignored.isValid(1);throw new AssertionError("hostname verification bypassed");}catch(SQLException expected){/* no plaintext fallback */}});
            check("SQL constraints reject unsupported record namespaces",()->{try(Connection c=config.connect();Statement s=c.createStatement()){s.execute("INSERT INTO workspace_records(namespace,record_id,db_revision,nonce,ciphertext) VALUES('bad','invalid',1,REPEAT('x',12),'invalid')");throw new AssertionError("constraint ignored");}catch(SQLException expected){eq(expected.getErrorCode(),3819);}});
            check("record ciphertext and username lookup contain no raw credentials or amounts",()->{String id=create(a,owner);a.edit(owner,id,command(a.readCase(owner,id),"PROPOSE","field","SALARY","text","800000.00","unit","RUPEES"));try(Connection c=admin.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT ciphertext,lookup_tag FROM workspace_records")){boolean tag=false;while(r.next()){String raw=new String(r.getBytes(1),StandardCharsets.ISO_8859_1);for(String secret:List.of(password,"sql_owner","800000.00"))eq(raw.contains(secret),false);if(r.getBytes(2)!=null){eq(r.getBytes(2).length,32);tag=true;}}eq(tag,true);}});
            check("a callback rejection rolls back its pending records",()->{long before=one.read(state->(long)Workspace.table(state,"quotes").size());problem("TEST_REJECTED",()->one.transaction(state->{Workspace.table(state,"quotes").put("rollback-marker",Map.of("value","uncommitted"));throw new Workspace.Problem(409,"TEST_REJECTED");}));eq(two.read(state->(long)Workspace.table(state,"quotes").size()),before);});
            check("database failure between case and receipt writes rolls both back",()->{String id=create(a,owner);Map<String,Object> current=a.readCase(owner,id),request=command(current,"PROPOSE","field","SALARY","text","1 lakh","unit","");try(Connection c=admin.connect();Statement s=c.createStatement()){s.execute("CREATE TRIGGER reject_receipts BEFORE INSERT ON workspace_records FOR EACH ROW SET NEW.ciphertext=IF(NEW.namespace='receipts',NULL,NEW.ciphertext)");}try{problem("MYSQL_STORAGE_UNAVAILABLE",()->a.edit(owner,id,request));eq(b.readCase(owner,id),current);eq(two.read(state->Workspace.table(state,"receipts").get(owner+":"+request.get("request_id"))),null);}finally{try(Connection c=admin.connect();Statement s=c.createStatement()){s.execute("DROP TRIGGER reject_receipts");}}eq(a.edit(owner,id,request).get("status"),"APPLIED");});
            check("different existing records commit while another callback remains open",()->{String x="parallel-a",y="parallel-b";while(ConcurrentMysqlStore.shard(x)==ConcurrentMysqlStore.shard(y))y+="x";final String secondId=y;one.transaction(state->{Workspace.table(state,"operations").put(x,Map.of("value",0L));Workspace.table(state,"operations").put(secondId,Map.of("value",0L));return null;});var pool=Executors.newFixedThreadPool(2);CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1);try{var first=pool.submit(()->one.transaction(state->{var row=Workspace.table(state,"operations");row.put(x,Map.of("value",1L));held.countDown();try{if(!release.await(6,TimeUnit.SECONDS))throw new AssertionError("release timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}return null;}));eq(held.await(2,TimeUnit.SECONDS),true);var second=pool.submit(()->two.transaction(state->{Workspace.table(state,"operations").put(secondId,Map.of("value",2L));return null;}));second.get(3,TimeUnit.SECONDS);eq(two.read(state->Json.map(Workspace.table(state,"operations").get(secondId)).get("value")),2L);release.countDown();first.get(4,TimeUnit.SECONDS);}finally{release.countDown();pool.shutdownNow();}});

            check("two SQL-backed writers from one case version cannot both apply",()->{var pool=Executors.newFixedThreadPool(2);try{for(int i=0;i<4;i++){String id=create(a,owner);var row=a.readCase(owner,id);var x=command(row,"PROPOSE","field","SALARY","text","1 lakh","unit","");var y=command(row,"PROPOSE","field","SALARY","text","2 lakh","unit","");CountDownLatch start=new CountDownLatch(1);var p=pool.submit(()->{start.await();return status(()->a.edit(owner,id,x));});var q=pool.submit(()->{start.await();return status(()->b.edit(owner,id,y));});start.countDown();List<String> statuses=new ArrayList<>(List.of(p.get(),q.get()));statuses.sort(String::compareTo);eq(statuses,List.of("APPLIED","STALE_CASE"));concurrentRounds++;}}finally{pool.shutdownNow();}});
            check("concurrent identical SQL-backed requests produce one edit and one replay",()->{String id=create(a,owner);var request=command(a.readCase(owner,id),"PROPOSE","field","SALARY","text","1 lakh","unit","");var pool=Executors.newFixedThreadPool(2);try{var first=pool.submit(()->a.edit(owner,id,request).get("status"));var second=pool.submit(()->b.edit(owner,id,request).get("status"));List<Object> statuses=new ArrayList<>(List.of(first.get(),second.get()));statuses.sort((x,y)->x.toString().compareTo(y.toString()));eq(statuses,List.of("APPLIED","REPLAYED"));eq(a.readCase(owner,id).get("revision"),2L);}finally{pool.shutdownNow();}});
            check("lost acknowledgement after a real commit safely replays once",()->{String id=create(a,owner);var request=command(a.readCase(owner,id),"PROPOSE","field","SALARY","text","2 lakh","unit","");AtomicBoolean lose=new AtomicBoolean(true);try(ConcurrentMysqlStore lost=new ConcurrentMysqlStore(config,key,c->{if(lose.compareAndSet(true,false))throw new SQLException("simulated lost acknowledgement after actual commit");})){Workspace uncertain=new Workspace(lost,time);problem("STORAGE_OUTCOME_UNKNOWN",()->uncertain.edit(owner,id,request));eq(b.readCase(owner,id).get("revision"),2L);eq(b.edit(owner,id,request).get("status"),"REPLAYED");eq(b.readCase(owner,id).get("revision"),2L);}});
            check("moving ciphertext to a different case is rejected by record binding",()->{String x=create(a,owner),y=create(a,owner);byte[] nonce,ciphertext;long version;try(Connection c=admin.connect();var s=c.prepareStatement("SELECT nonce,ciphertext,db_revision FROM workspace_records WHERE namespace='cases' AND record_id=?")){s.setString(1,y);try(ResultSet r=s.executeQuery()){r.next();nonce=r.getBytes(1);ciphertext=r.getBytes(2);version=r.getLong(3);}}byte[] oldNonce,oldBytes;long oldVersion;try(Connection c=admin.connect();var s=c.prepareStatement("SELECT nonce,ciphertext,db_revision FROM workspace_records WHERE namespace='cases' AND record_id=?")){s.setString(1,x);try(ResultSet r=s.executeQuery()){r.next();oldNonce=r.getBytes(1);oldBytes=r.getBytes(2);oldVersion=r.getLong(3);}}try{replaceCipher(admin,x,nonce,ciphertext,version);problem("MYSQL_STORAGE_UNAVAILABLE",()->b.readCase(owner,x));}finally{replaceCipher(admin,x,oldNonce,oldBytes,oldVersion);}eq(b.readCase(owner,x).get("id"),x);});
            check("revocation from one store denies reads and prior note retries from another",()->{String id=create(a,owner);a.grant(owner,id,body("request_id",Workspace.id(),"expected_revision",a.readCase(owner,id).get("revision"),"preparer_username","sql_staff","expires_days",7L,"consent",true));var note=body("request_id",Workspace.id(),"expected_revision",b.readCase(preparer,id).get("revision"),"text","SQL preparation note");b.note(preparer,id,note);String grant=(String)a.grants(owner,id).get(0).get("id");a.revoke(owner,id,body("request_id",Workspace.id(),"expected_revision",a.readCase(owner,id).get("revision"),"grant_id",grant));problem("CASE_NOT_FOUND",()->b.readCase(preparer,id));problem("CASE_NOT_FOUND",()->b.note(preparer,id,note));});
            check("immutable quotes retain the original SQL-backed price version",()->{var price=body("request_id",Workspace.id(),"plan","FIRM_WORKSPACE","amount_paise",12500L,"effective_at",time.instant().plusSeconds(1).toString(),"label","SQL planning price");a.publishPrice(operator,price);time.now=time.now.plusSeconds(1);var request=body("request_id",Workspace.id(),"plan","FIRM_WORKSPACE");a.quote(owner,request);var quote=b.quotes(owner).get(0);var next=new LinkedHashMap<>(price);next.put("request_id",Workspace.id());next.put("amount_paise",25000L);next.put("effective_at",time.instant().plusSeconds(1).toString());b.publishPrice(operator,next);eq(a.quotes(owner).get(0),quote);eq(quote.get("payment_available"),false);});
            check("deleted cases remain deleted after replay on another store",()->{var request=body("request_id",Workspace.id(),"title","SQL deleted case");String id=(String)a.createCase(owner,request).get("id");a.deleteCase(owner,id,body("expected_revision",a.readCase(owner,id).get("revision"),"confirm","DELETE"));eq(b.createCase(owner,request).get("status"),"REPLAYED");problem("CASE_NOT_FOUND",()->b.readCase(owner,id));});
            check("SQL accounting matches encrypted record sizes after edits and deletion",()->{try(Connection c=admin.connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT (SELECT SUM(payload_bytes) FROM workspace_concurrency),(SELECT COALESCE(SUM(OCTET_LENGTH(ciphertext)),0) FROM workspace_records)")){r.next();eq(r.getLong(1),r.getLong(2));}});
            check("SQL persistence never grants a numerical result or filing capability",()->{String id=create(a,owner);var row=b.readCase(owner,id);eq(row.get("tax_values_released"),false);eq(row.get("filing_available"),false);eq(row.get("ca_approval"),false);eq(a.admin(operator).get("mysql_backend_active"),true);});
            check("legacy adapter refuses schema 2 instead of sharing incompatible locks",()->{try(MysqlStore legacy=new MysqlStore(config,key)){legacy.backend();throw new AssertionError("mixed modes allowed");}catch(SQLException expected){/* schema mismatch */}});
            check("scan phantoms cause a fresh callback before publishing dependent state",()->{var pool=Executors.newFixedThreadPool(2);CountDownLatch observed=new CountDownLatch(1),release=new CountDownLatch(1);AtomicBoolean initial=new AtomicBoolean(true);try{var first=pool.submit(()->one.transaction(state->{Map<String,Object> rows=Workspace.table(state,"operations");boolean found=rows.values().stream().map(Json::map).anyMatch(row->Boolean.TRUE.equals(row.get("phantom")));if(initial.compareAndSet(true,false)){observed.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("timeout");}catch(InterruptedException e){throw new AssertionError(e);}}rows.put("phantom-result",Map.of("observed",found));return found;}));eq(observed.await(2,TimeUnit.SECONDS),true);two.transaction(state->{Workspace.table(state,"operations").put("phantom-source",Map.of("phantom",true));return null;});release.countDown();eq(first.get(5,TimeUnit.SECONDS),true);}finally{release.countDown();pool.shutdownNow();}});
            check("read dependency validation prevents two-record write skew",()->{String x="skew-a",y="skew-b";one.transaction(state->{Workspace.table(state,"operations").put(x,Map.of("active",true));Workspace.table(state,"operations").put(y,Map.of("active",true));return null;});var pool=Executors.newFixedThreadPool(2);var barrier=new java.util.concurrent.CyclicBarrier(2);try{List<java.util.concurrent.Future<?>> futures=new ArrayList<>();for(int at=0;at<2;at++){final int index=at;AtomicBoolean initial=new AtomicBoolean(true);ConcurrentMysqlStore selected=index==0?one:two;futures.add(pool.submit(()->selected.transaction(state->{var rows=Workspace.table(state,"operations");boolean left=Boolean.TRUE.equals(Json.map(rows.get(x)).get("active")),right=Boolean.TRUE.equals(Json.map(rows.get(y)).get("active"));if(initial.compareAndSet(true,false))try{barrier.await(4,TimeUnit.SECONDS);}catch(Exception e){throw new AssertionError(e);}if(left&&right)rows.put(index==0?x:y,Map.of("active",false));return null;})));}for(var f:futures)f.get(8,TimeUnit.SECONDS);long active=one.read(state->List.of(x,y).stream().filter(id->Boolean.TRUE.equals(Json.map(Workspace.table(state,"operations").get(id)).get("active"))).count());eq(active,1L);}finally{pool.shutdownNow();}});
            check("capacity predicate rejects a concurrent oversubscription atomically",()->{long before=one.read(state->(long)Workspace.table(state,"quotes").size());var pool=Executors.newFixedThreadPool(2);var barrier=new java.util.concurrent.CyclicBarrier(2);try{List<java.util.concurrent.Future<String>> futures=new ArrayList<>();for(int at=0;at<2;at++){ConcurrentMysqlStore selected=at==0?one:two;String marker="capacity-"+at;AtomicBoolean initial=new AtomicBoolean(true);futures.add(pool.submit(()->status(()->selected.transaction(state->{var rows=Workspace.table(state,"quotes");Capacity.requireSpace(rows,before+1,"CAPACITY_TEST");if(initial.compareAndSet(true,false))try{barrier.await(4,TimeUnit.SECONDS);}catch(Exception e){throw new AssertionError(e);}rows.put(marker,Map.of("marker",marker));return null;}))));}List<String> outcomes=new ArrayList<>();for(var f:futures)outcomes.add(f.get(8,TimeUnit.SECONDS));outcomes.sort(String::compareTo);eq(outcomes,List.of("APPLIED","CAPACITY_TEST"));eq(one.read(state->(long)Workspace.table(state,"quotes").size()),before+1);}finally{pool.shutdownNow();}});
            check("session revocation between authorization and commit rejects the pending edit",()->{
                String id=create(a,owner);var request=command(a.readCase(owner,id),"RENAME","title","Must not publish after session revocation");long epoch=a.authenticationEpoch(owner);CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1);AtomicBoolean initial=new AtomicBoolean(true);
                DataStore delayed=new DataStore(){@Override public String backend(){return one.backend();}@Override public void close(){ }@Override public <T>T read(java.util.function.Function<Map<String,Object>,T> work){return one.read(work);}@Override public <T>T transaction(java.util.function.Function<Map<String,Object>,T> work){return one.transaction(state->{T result=work.apply(state);if(initial.compareAndSet(true,false)){held.countDown();try{if(!release.await(6,TimeUnit.SECONDS))throw new AssertionError("timeout");}catch(InterruptedException e){throw new AssertionError(e);}}return result;});}};
                Workspace pending=new Workspace(delayed,time);AccountSecurity security=new AccountSecurity(two,b,time);var pool=Executors.newSingleThreadExecutor();try{var result=pool.submit(()->{pending.bindSession(owner,epoch);try{return status(()->pending.edit(owner,id,request));}finally{pending.clearSession();}});eq(held.await(2,TimeUnit.SECONDS),true);security.command(owner,body("operation","REVOKE_OTHER_SESSIONS","expected_security_revision",security.view(owner).get("security_revision"),"password",password,"factor_method","","factor_code",""),false);release.countDown();eq(result.get(8,TimeUnit.SECONDS),"SESSION_ENDED");eq(a.readCase(owner,id).get("title"),"SQL sample case");eq(a.readCase(owner,id).get("revision"),1L);}finally{release.countDown();pool.shutdownNow();}
            });
            check("lost acknowledgement of MFA activation cannot reissue plaintext recovery codes",()->{
                String actor=(String)a.register(body("username","sql_uncertain_mfa","display_name","Uncertain MFA fixture","password",password)).get("id");AccountSecurity normal=new AccountSecurity(two,b,time);var setup=normal.command(actor,body("operation","START_ENROLLMENT","expected_security_revision",0L,"password",password,"factor_method","","factor_code",""),false).response();var request=body("operation","CONFIRM_ENROLLMENT","expected_security_revision",1L,"password",password,"factor_method","TOTP","factor_code",Totp.at((String)setup.get("secret"),time.instant().getEpochSecond()/30,6),"setup_id",setup.get("setup_id"));AtomicBoolean lose=new AtomicBoolean(true);
                try(ConcurrentMysqlStore lost=new ConcurrentMysqlStore(config,key,c->{if(lose.compareAndSet(true,false))throw new SQLException("simulated lost MFA activation acknowledgement");})){AccountSecurity uncertain=new AccountSecurity(lost,new Workspace(lost,time),time);problem("STORAGE_OUTCOME_UNKNOWN",()->uncertain.command(actor,request,false));}
                eq(normal.view(actor).get("mfa_enabled"),true);eq(normal.view(actor).get("recovery_codes_remaining"),10);eq(b.authenticationEpoch(actor),1L);problem("STALE_SECURITY_SETTINGS",()->normal.command(actor,request,false));eq(normal.view(actor).containsKey("recovery_codes"),false);eq(normal.view(actor).containsKey("secret"),false);
            });
            check("revocation during an in-flight preparation comment blocks publication",()->{String id=create(a,owner);a.grant(owner,id,body("request_id",Workspace.id(),"expected_revision",a.readCase(owner,id).get("revision"),"preparer_username","sql_staff","expires_days",7L,"consent",true));String grant=(String)a.grants(owner,id).get(0).get("id");var request=body("request_id",Workspace.id(),"expected_revision",a.readCase(owner,id).get("revision"),"text","Must not survive revocation");CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1);AtomicBoolean initial=new AtomicBoolean(true);DataStore delayed=new DataStore(){@Override public String backend(){return one.backend();}@Override public void close(){ }@Override public <T>T read(java.util.function.Function<Map<String,Object>,T> work){return one.read(work);}@Override public <T>T transaction(java.util.function.Function<Map<String,Object>,T> work){return one.transaction(state->{T result=work.apply(state);if(initial.compareAndSet(true,false)){held.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("timeout");}catch(InterruptedException e){throw new AssertionError(e);}}return result;});}};Workspace delayedWorkspace=new Workspace(delayed,time);var pool=Executors.newSingleThreadExecutor();try{var result=pool.submit(()->status(()->delayedWorkspace.note(preparer,id,request)));eq(held.await(2,TimeUnit.SECONDS),true);b.revoke(owner,id,body("request_id",Workspace.id(),"expected_revision",b.readCase(owner,id).get("revision"),"grant_id",grant));release.countDown();eq(result.get(8,TimeUnit.SECONDS),"CASE_NOT_FOUND");eq(Json.list(a.readCase(owner,id).get("preparation_notes")).size(),0);}finally{release.countDown();pool.shutdownNow();}});
            check("encrypted stored payload can exceed the legacy 16 MiB aggregate",()->{String payload="z".repeat(210000);one.transaction(state->{for(int at=0;at<90;at++)Workspace.table(state,"operations").put("large-record-"+at,Map.of("synthetic",true,"payload",payload));return null;});try(Connection c=admin.connect();Statement q=c.createStatement();ResultSet rows=q.executeQuery("SELECT SUM(payload_bytes),SUM(record_count) FROM workspace_concurrency")){rows.next();eq(rows.getLong(1)>16_777_216,true);eq(rows.getLong(2)>90,true);}eq(Json.map(two.read(state->Workspace.table(state,"operations").get("large-record-89"))).get("synthetic"),true);});
            one.transaction(state->{Workspace.table(state,"receipts").put("crash-probe",Map.of("marker","COMMITTED_BEFORE_MYSQL_PROCESS_CRASH"));return null;});
        }
        Map<String,Object> result=Map.of("concurrent_mysql_named_groups",passed,"mysql_version",serverVersion,"jdbc_driver_version",driverVersion,"sql_concurrent_distinct_writer_rounds",concurrentRounds,"actual_mysql",true,"certificate_identity_verified",true,"production_ready",false);Files.write(report,Json.bytes(result));System.out.println(Json.encode(result));
    }
    private static void replaceCipher(SqlConfig admin,String id,byte[] nonce,byte[] ciphertext,long version)throws SQLException{try(Connection c=admin.connect();var s=c.prepareStatement("UPDATE workspace_records SET nonce=?,ciphertext=?,db_revision=? WHERE namespace='cases' AND record_id=?")){s.setBytes(1,nonce);s.setBytes(2,ciphertext);s.setLong(3,version);s.setString(4,id);s.executeUpdate();}}
}
